import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  // Root container – will be positioned by the adapter
  const root = new Group();

  // --- Geometry -------------------------------------------------------------
  // Atlas region (fallback to full image size if not supplied)
  const atlasRect = (config.atlas && config.atlas.sourceRect) || [0, 0, 512, 320];
  const width = atlasRect[2];
  const height = atlasRect[3];
  const aspect = width / height;
  const planeWidth = aspect; // 1 unit tall, width based on aspect
  const planeHeight = 1;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // --- Material --------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    alphaTest: 0.5,
    // map will be assigned once the texture loads
    map: null,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // --- Billboard (face camera) ------------------------------------------------
  const onBeforeRender = (renderer, scene, camera) => {
    mesh.lookAt(camera.position);
  };
  mesh.onBeforeRender = onBeforeRender;

  // --- Load texture -----------------------------------------------------------
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = texture(tex);
      material.needsUpdate = true;
    });
  }

  // --- Text ---------------------------------------------------------------
  const rawItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const items = Array.isArray(rawItems) ? rawItems : [{ text: rawItems }];

  for (const item of items) {
    const content = item.text ?? item.content ?? '';
    if (!content) continue;

    const txt = ctx.fontAtlas.createText(content, {
      fontSize: (item.typography && item.typography.fontSize) || 96,
      color: (config.visual && config.visual.colors && config.visual.colors.paper) || '#e8ecf2',
      align: 'center',
    });

    // Position text slightly above the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    mesh.add(txt);
  }

  // --- Cleanup --------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    // Remove the before‑render hook
    mesh.onBeforeRender = null;

    // Kill any GSAP timelines that might have been created (none in this node)
    gsap.killTweensOf(mesh);
  };

  // No interactive handlers required for this static node
  root.userData.handlers = {};

  return root;
}
